insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,clinical_judgment_step,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale) values
('84000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001',1,'The RN is reassessing a client being evaluated for acute coronary syndrome. Which change most strongly suggests worsening perfusion and requires immediate priority reassessment?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Acute Coronary Syndrome','Physiological Integrity','Recognize Cues','medium','New hypotension with cool, clammy skin and increasing confusion suggests deteriorating systemic perfusion. The RN should recognize the cluster as instability and immediately reassess and coordinate the appropriate response.','Persistent anxiety, a request for family contact, or an unchanged mild symptom may require attention but do not indicate the same degree of circulatory deterioration.','RN: in ACS, a falling pressure plus altered mentation and cool skin signals threatened perfusion.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN synthesis of multiple changing cues to identify cardiovascular instability.','RN-specific because the learner integrates several assessment findings and reprioritizes the overall nursing response.'),
('84000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000002',1,'The LPN/VN is monitoring a client being evaluated for acute coronary syndrome. Which new finding should be reported immediately to the RN or appropriate emergency response according to the setting?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Acute Coronary Syndrome','Physiological Integrity','Recognize Cues','medium','New confusion accompanied by cool, clammy skin and blood pressure below baseline represents a significant change that may reflect worsening perfusion. The LPN/VN should obtain focused data, maintain safety, and escalate promptly.','A routine request, unchanged chronic finding, or stable symptom does not carry the same urgency as a new cluster suggesting impaired perfusion.','PN: compare with baseline; new perfusion changes require focused data and prompt escalation.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN recognition of significant change, focused monitoring, safety, and communication.','PN-specific because the learner detects deterioration from baseline and communicates it promptly within the established care structure.'),
('84000000-0000-4000-8000-000000000003','83000000-0000-4000-8000-000000000003',1,'The RN is evaluating a client after an intervention for a symptomatic dysrhythmia. Which finding best indicates improved perfusion?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Dysrhythmias','Physiological Integrity','Evaluate Outcomes','medium','Improved mentation, warmer skin, and blood pressure returning toward the client baseline indicate improved organ perfusion. Evaluation should focus on the client response rather than rhythm appearance alone.','A monitor tracing without corresponding clinical improvement does not by itself establish adequate perfusion.','RN evaluation: improvement is demonstrated by the client, not merely by the monitor.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN evaluation of intervention effectiveness using hemodynamic and whole-client findings.','RN-specific because the learner evaluates whether the overall response to care restored adequate perfusion.'),
('84000000-0000-4000-8000-000000000004','83000000-0000-4000-8000-000000000004',1,'The LPN/VN is monitoring a client after treatment for a symptomatic dysrhythmia. Which finding should be communicated as evidence that the client is improving?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Dysrhythmias','Physiological Integrity','Evaluate Outcomes','medium','Improved alertness, decreased dizziness, and blood pressure moving toward baseline are focused findings consistent with improved perfusion and should be documented and communicated according to the care plan.','A rhythm display alone is not enough to determine the client response when symptoms and perfusion findings are available.','PN monitoring: compare symptoms and vital signs with baseline and report the response.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN focused monitoring of response to treatment and communication of findings.','PN-specific because the learner collects and reports focused outcome data within the established plan.'),
('84000000-0000-4000-8000-000000000005','83000000-0000-4000-8000-000000000005',1,'The RN assesses a client with markedly elevated blood pressure. Which additional finding makes the situation most concerning for acute target-organ involvement?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Hypertension','Physiological Integrity','Analyze Cues','medium','New neurologic change such as confusion or focal deficit accompanying markedly elevated blood pressure raises concern for acute target-organ involvement and requires prompt assessment and escalation.','An isolated elevated reading without acute symptoms still requires appropriate evaluation, but new neurologic dysfunction changes the urgency.','RN: severe pressure plus new organ dysfunction is more urgent than the number alone.','Original NursePrepIQ pilot item; avoids a single numeric threshold and requires clinical editorial validation. Not an NCSBN item.','pilot','RN analysis of blood-pressure data together with signs of acute target-organ dysfunction.','RN-specific because the learner synthesizes the vital-sign abnormality with comprehensive assessment findings to determine urgency.'),
('84000000-0000-4000-8000-000000000006','83000000-0000-4000-8000-000000000006',1,'The LPN/VN obtains a blood pressure much higher than the client documented baseline. Which accompanying finding should prompt the most immediate communication?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Hypertension','Physiological Integrity','Recognize Cues','medium','A new neurologic change such as confusion, weakness, or difficulty speaking accompanying a major blood-pressure change is a significant finding requiring prompt focused assessment, safety measures, and communication.','Routine questions or stable chronic findings do not have the same implication for acute deterioration.','PN: a major vital-sign change plus new neurologic symptoms needs prompt escalation.','Original NursePrepIQ pilot item; avoids a single numeric threshold and requires clinical editorial validation. Not an NCSBN item.','pilot','PN recognition of abnormal vital-sign trends and new symptoms requiring prompt reporting.','PN-specific because the learner compares current findings with baseline, gathers focused data, protects the client, and escalates the change.'),
('84000000-0000-4000-8000-000000000007','83000000-0000-4000-8000-000000000007',1,'The RN compares findings in two clients with peripheral vascular disease. Which finding is more characteristic of chronic venous insufficiency than peripheral arterial disease?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Peripheral Vascular Disease','Physiological Integrity','Analyze Cues','medium','Dependent lower-extremity edema with brownish skin discoloration is more characteristic of chronic venous insufficiency. Arterial disease more often produces diminished pulses, coolness, pallor, and ischemic pain patterns.','Cool pale skin, diminished pulses, and pain associated with inadequate arterial flow support arterial rather than venous disease.','Venous = congestion and edema; arterial = reduced flow, coolness, pallor, weak pulses.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','RN comparative assessment and pattern recognition across arterial and venous vascular disorders.','RN-specific because the learner synthesizes assessment patterns to distinguish vascular mechanisms and guide nursing priorities.'),
('84000000-0000-4000-8000-000000000008','83000000-0000-4000-8000-000000000008',1,'The LPN/VN is reinforcing an established skin-protection plan for a client with peripheral arterial disease. Which client action should the LPN/VN correct?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Peripheral Vascular Disease','Physiological Integrity','Take Action','easy','Applying a heating pad directly to a poorly perfused foot can cause thermal injury because tissue sensation and circulation may be impaired. The LPN/VN should reinforce the established safety plan and report skin or perfusion changes.','Routine inspection, protective footwear, and following the established care plan support injury prevention.','PN vascular safety: protect poorly perfused tissue from heat, pressure, and injury.','Original NursePrepIQ pilot item; requires clinical editorial validation before production use. Not an NCSBN item.','pilot','PN reinforcement of established vascular skin-safety teaching and prevention of injury.','PN-specific because the learner reinforces an established plan and identifies an unsafe client action requiring correction.')
insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values
('84000000-0000-4000-8000-000000000001','a','The client asks whether a family member can visit.',false,'This is not a perfusion indicator.',1),('84000000-0000-4000-8000-000000000001','b','Blood pressure falls below baseline while the client becomes cool, clammy, and confused.',true,'This cluster suggests worsening systemic perfusion.',2),('84000000-0000-4000-8000-000000000001','c','The client remains mildly anxious about testing.',false,'Anxiety alone does not indicate the same degree of deterioration.',3),('84000000-0000-4000-8000-000000000001','d','The client asks when the next meal will arrive.',false,'This is nonurgent.',4),
('84000000-0000-4000-8000-000000000002','a','The client asks for a blanket.',false,'This routine request is not evidence of acute deterioration.',1),('84000000-0000-4000-8000-000000000002','b','The client has unchanged mild anxiety.',false,'An unchanged finding is less urgent than new deterioration.',2),('84000000-0000-4000-8000-000000000002','c','The client becomes confused and clammy and the blood pressure falls below baseline.',true,'These are significant new perfusion changes requiring prompt escalation.',3),('84000000-0000-4000-8000-000000000002','d','The client asks when routine medications are due.',false,'This does not indicate acute deterioration.',4),
('84000000-0000-4000-8000-000000000003','a','The monitor rhythm appears more regular, but the client remains confused and hypotensive.',false,'Clinical instability remains despite the monitor appearance.',1),('84000000-0000-4000-8000-000000000003','b','The client is more alert, skin is warmer, and blood pressure is returning toward baseline.',true,'These findings support improved perfusion.',2),('84000000-0000-4000-8000-000000000003','c','The client asks what time it is.',false,'This alone does not establish improved perfusion.',3),('84000000-0000-4000-8000-000000000003','d','The monitor alarm volume has been reduced.',false,'Alarm settings do not measure the client response.',4),
('84000000-0000-4000-8000-000000000004','a','The client reports less dizziness and is more alert, with blood pressure moving toward baseline.',true,'Focused symptom and vital-sign improvement supports improved perfusion.',1),('84000000-0000-4000-8000-000000000004','b','The monitor tracing looks different but the client remains dizzy.',false,'The client response remains concerning.',2),('84000000-0000-4000-8000-000000000004','c','The client requests a different television channel.',false,'This does not meaningfully evaluate perfusion.',3),('84000000-0000-4000-8000-000000000004','d','The room is quieter after an alarm is silenced.',false,'This is not an outcome measure.',4),
('84000000-0000-4000-8000-000000000005','a','The client reports a new difficulty speaking and appears confused.',true,'New neurologic dysfunction raises concern for acute target-organ involvement.',1),('84000000-0000-4000-8000-000000000005','b','The client says the blood-pressure cuff feels tight.',false,'This is expected during measurement and does not indicate target-organ dysfunction.',2),('84000000-0000-4000-8000-000000000005','c','The client asks for information about reducing dietary sodium.',false,'Teaching is important but not an acute organ-dysfunction cue.',3),('84000000-0000-4000-8000-000000000005','d','The client reports having hypertension for several years.',false,'History alone does not establish acute target-organ injury.',4),
('84000000-0000-4000-8000-000000000006','a','The client asks when the next blood-pressure check is scheduled.',false,'This is not evidence of acute deterioration.',1),('84000000-0000-4000-8000-000000000006','b','The client has new confusion and difficulty speaking.',true,'New neurologic changes accompanying a major blood-pressure change require prompt communication.',2),('84000000-0000-4000-8000-000000000006','c','The client says the cuff is uncomfortable.',false,'Cuff discomfort is not the priority finding.',3),('84000000-0000-4000-8000-000000000006','d','The client reports a longstanding family history of hypertension.',false,'Family history is not an acute change.',4),
('84000000-0000-4000-8000-000000000007','a','A cool pale foot with diminished pedal pulses.',false,'This is more characteristic of arterial insufficiency.',1),('84000000-0000-4000-8000-000000000007','b','Dependent edema with brownish discoloration near the lower leg and ankle.',true,'This pattern is characteristic of chronic venous congestion.',2),('84000000-0000-4000-8000-000000000007','c','Pain associated with reduced arterial blood flow.',false,'This supports arterial disease.',3),('84000000-0000-4000-8000-000000000007','d','Markedly diminished pulses with a cold extremity.',false,'This supports arterial perfusion impairment.',4),
('84000000-0000-4000-8000-000000000008','a','Inspecting the feet regularly for skin injury.',false,'Regular inspection supports prevention.',1),('84000000-0000-4000-8000-000000000008','b','Wearing protective, properly fitting footwear.',false,'Protective footwear helps reduce injury risk.',2),('84000000-0000-4000-8000-000000000008','c','Applying a heating pad directly to a cold foot.',true,'Direct heat can cause injury to poorly perfused tissue.',3),('84000000-0000-4000-8000-000000000008','d','Following the established skin-care plan.',false,'Following the established plan is appropriate.',4)
